using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using ForteMove.Models.Common;using ForteMove.Models.Fleet;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Admin{public partial class EditBus:AdminPage{private long Id{get{long v;return long.TryParse(Request.QueryString["id"],out v)?v:0;}}protected void Page_Load(object sender,EventArgs e){if(!IsPostBack)Bind();}private void Bind(){BusDetails b=ServiceFactory.CreateBusService().GetBusDetails(Id);if(b==null){Response.Redirect(ResolveUrl("~/Admin/FleetList.aspx"),true);return;}var options=ServiceFactory.CreateBusService().GetRegistrationOptions().Categories;ddlCategory.DataSource=options;ddlCategory.DataTextField="DisplayName";ddlCategory.DataValueField="Id";ddlCategory.DataBind();ddlCategory.SelectedValue=b.BusCategoryId.ToString(CultureInfo.InvariantCulture);lnkReturnToService.NavigateUrl="~/Admin/Maintenance/ReturnToService.aspx?id="+b.BusId;litBusIdentity.Text=Server.HtmlEncode(b.FleetNumber+" · "+b.Make+" "+b.Model+" · "+b.RegistrationNumber);txtCapacity.Text=b.PassengerCapacity.ToString(CultureInfo.InvariantCulture);txtGvm.Text=b.GrossVehicleMassKg.HasValue?b.GrossVehicleMassKg.Value.ToString(CultureInfo.InvariantCulture):string.Empty;txtLicence.Text=b.LicenceExpiryDate.ToString("yyyy-MM-dd");txtRoadworthy.Text=b.RoadworthyExpiryDate.ToString("yyyy-MM-dd");txtInsurance.Text=b.InsuranceExpiryDate.ToString("yyyy-MM-dd");ddlStatus.SelectedValue=b.BaseOperationalState.ToString();hidRowVersion.Value=Convert.ToBase64String(b.RowVersion);}protected void btnSave_Click(object sender,EventArgs e){IList<ValidationError> binding=new List<ValidationError>();int category,capacity,gvm;BusOperationalState state;var result=ServiceFactory.CreateBusService().UpdateBusEligibility(new UpdateBusEligibilityRequest{BusId=Id,BusCategoryId=int.TryParse(ddlCategory.SelectedValue,out category)?category:(int?)null,PassengerCapacity=int.TryParse(txtCapacity.Text,out capacity)?capacity:(int?)null,GrossVehicleMassKg=int.TryParse(txtGvm.Text,out gvm)?gvm:(int?)null,LicenceExpiryDate=ParseDate(txtLicence.Text,"LicenceExpiryDate",binding),RoadworthyExpiryDate=ParseDate(txtRoadworthy.Text,"RoadworthyExpiryDate",binding),InsuranceExpiryDate=ParseDate(txtInsurance.Text,"InsuranceExpiryDate",binding),BaseOperationalState=Enum.TryParse(ddlStatus.SelectedValue,out state)?state:(BusOperationalState?)null,RowVersion=ParseRv(hidRowVersion.Value)},CurrentPrincipalContext.UserAccountId);if(binding.Count>0){Show(binding);return;}if(!result.Succeeded){Show(result.Errors);return;}FlashMessageStore.Put(Session,"Bus assignment readiness was updated.",false);Response.Redirect(ResolveUrl("~/Admin/FleetDetails.aspx?id="+Id),true);}private static DateTime? ParseDate(string text,string field,IList<ValidationError> e){DateTime v;if(DateTime.TryParseExact(text,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out v))return v;e.Add(new ValidationError(field,"Enter a valid date."));return null;}private static byte[] ParseRv(string value){try{return Convert.FromBase64String(value);}catch{return null;}}private void Show(IEnumerable<ValidationError> e){pnlErrors.Visible=true;rptErrors.DataSource=e;rptErrors.DataBind();}}}
